<?php
require 'header.php';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$pdo=db();$action=$_POST['action']??'';
 if($action==='toggle'){$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);if($id){$s=$pdo->prepare('SELECT active,title FROM flash_sales WHERE id=?');$s->execute([$id]);$sale=$s->fetch();if($sale){$next=!(int)$sale['active'];$pdo->beginTransaction();$pdo->prepare('UPDATE flash_sales SET active=? WHERE id=?')->execute([$next?1:0,$id]);$pdo->prepare('INSERT INTO admin_audit_log(admin_id,action,entity_type,entity_id,detail) VALUES(?,?,?,?,?)')->execute([$_SESSION['admin_id'],'flash_sale_toggle','flash_sale',(string)$id,$sale['title'].' active='.($next?'1':'0')]);$pdo->commit();flash('success','Promotion state updated.');}}header('Location: flash-sales.php');exit;}
 $title=trim($_POST['title']??'');$pid=filter_var($_POST['product_id']??null,FILTER_VALIDATE_INT);$price=filter_var($_POST['sale_price']??null,FILTER_VALIDATE_FLOAT);$start=strtotime($_POST['starts_at']??'');$end=strtotime($_POST['ends_at']??'');$active=isset($_POST['active'])?1:0;
 if(!$title||!$pid||$price===false||$price<=0||!$start||!$end||$end<=$start){flash('error','Enter a title, valid product, positive price and valid promotion window.');}
 else{$s=db()->prepare('SELECT price FROM products WHERE id=?');$s->execute([$pid]);$regular=$s->fetchColumn();if($regular===false||$price>=(float)$regular){flash('error','Sale price must be below the product regular price.');}else{$pdo=db();$pdo->beginTransaction();$s=$pdo->prepare('INSERT INTO flash_sales(title,starts_at,ends_at,active) VALUES(?,?,?,?)');$s->execute([$title,date('Y-m-d H:i:s',$start),date('Y-m-d H:i:s',$end),$active]);$fid=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO flash_sale_products(flash_sale_id,product_id,sale_price) VALUES(?,?,?)')->execute([$fid,$pid,$price]);$pdo->prepare('INSERT INTO admin_audit_log(admin_id,action,entity_type,entity_id,detail) VALUES(?,?,?,?,?)')->execute([$_SESSION['admin_id'],'flash_sale_create','flash_sale',(string)$fid,$title]);$pdo->commit();flash('success','Flash sale saved.');header('Location: flash-sales.php');exit;}}
}
$products=db()->query('SELECT id,name,price FROM products ORDER BY name')->fetchAll();$sales=db()->query('SELECT fs.*,p.name product_name,fsp.sale_price,p.price regular_price FROM flash_sales fs JOIN flash_sale_products fsp ON fsp.flash_sale_id=fs.id JOIN products p ON p.id=fsp.product_id ORDER BY fs.starts_at DESC')->fetchAll();
?><div class="admin-title"><p>OFFERS</p><h2>Flash sales</h2></div><section class="admin-panel"><h3>Create promotion</h3><form method="post" class="settings-form"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="create"><label>Promotion title<input name="title" required maxlength="160"></label><label>Product<select name="product_id" required><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?> Â· <?=money($p['price'])?></option><?php endforeach?></select></label><label>Sale price (KSh)<input type="number" name="sale_price" min="1" step="0.01" required></label><label>Starts at<input type="datetime-local" name="starts_at" required></label><label>Ends at<input type="datetime-local" name="ends_at" required></label><label><input type="checkbox" name="active" checked> Active</label><button class="save">Create flash sale</button></form></section><section class="admin-panel"><h3>Existing promotions</h3><table><thead><tr><th>Promotion</th><th>Product</th><th>Price</th><th>Window</th><th>State</th><th>Action</th></tr></thead><tbody><?php foreach($sales as $s):?><tr><td><?=e($s['title'])?></td><td><?=e($s['product_name'])?></td><td><?=money($s['sale_price'])?> <small>(was <?=money($s['regular_price'])?>)</small></td><td><?=e($s['starts_at'])?> â€“ <?=e($s['ends_at'])?></td><td><?=$s['active']&&strtotime($s['starts_at'])<=time()&&strtotime($s['ends_at'])>time()?'Active':(strtotime($s['ends_at'])<=time()?'Expired':($s['active']?'Scheduled':'Inactive'))?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$s['id']?>"><button class="save"><?=$s['active']?'Deactivate':'Activate'?></button></form></td></tr><?php endforeach?></tbody></table></section><?php require 'footer.php';

